import{c as t,Q as a,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Designing loops with Fable 5","description":"","frontmatter":{},"headers":[],"relativePath":"research/tweets/2026-06-09-@RLanceMartin-071163.md","filePath":"research/tweets/2026-06-09-@RLanceMartin-071163.md","lastUpdated":1785909234000}'),i={name:"research/tweets/2026-06-09-@RLanceMartin-071163.md"};function n(s,e,l,c,d,g){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="designing-loops-with-fable-5" tabindex="-1">Designing loops with Fable 5 <a class="header-anchor" href="#designing-loops-with-fable-5" aria-label="Permalink to &quot;Designing loops with Fable 5&quot;">​</a></h1><p><strong>作者</strong>：Lance Martin (@RLanceMartin)<br><strong>發布時間</strong>：2026-06-09<br><strong>原始連結</strong>：<a href="https://x.com/rlancemartin/status/2064397389189071163" target="_blank" rel="noreferrer">https://x.com/rlancemartin/status/2064397389189071163</a><br><strong>類型</strong>：Twitter Article（Anthropic 官方工程師）<br><strong>統計</strong>：❤️ 5,672 · 🔁 717 · 🔖 15,005 · 👁 1,926,991</p><hr><h2 id="分析摘要" tabindex="-1">分析摘要 <a class="header-anchor" href="#分析摘要" aria-label="Permalink to &quot;分析摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Anthropic 工程師 Lance Martin 實測 Fable 5 兩個核心能力：(1) Parameter Golf 自我修正 loop——Fable 5 改進 training pipeline ~6× 於 Opus 4.7；(2) Continual Learning Bench 記憶任務——Fable 5 verification coverage 73% vs Opus 4.7 17%。核心建議：用 verifier sub-agent 取代 self-critique，設計 /goal + Outcomes 讓模型在 loop 中自我修正。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>Self-correction loop 設計</strong>：<code>/goal</code> in Claude Code + <code>Outcomes</code> in Claude Managed Agent（CMA）是讓 Fable 5 在 loop 中自我修正的官方 primitive；rubric/goal 提供環境反饋，Claude 自行 hillclimb</li><li><strong>Verifier sub-agent &gt; self-critique（關鍵洞察）</strong>：同一 model self-critique 在自己的 output 上分數會偏高；用獨立 context window 的 verifier sub-agent 效果更好——因為 grading 在無先前 justification 的全新脈絡中進行</li><li><strong>Parameter Golf 實驗</strong>：Fable 5 偏向 structural 變更（架構變更），顯示韌性；Opus 4.7 傾向 scalar 調整後跟隨相同模板。結果：Fable 5 改進 ~6×</li><li><strong>記憶 progression 模型</strong>：fail → investigate → verify → distill → consult 五步；Sonnet 4.6 停在 step 1（failure notes）；Opus 4.7 停在 step 3（17% verification）；Fable 5 達 step 4-5（73% verification + general rules）</li><li><strong>設計建議</strong>：不要直接 prompt/steer Fable 5，設計讓模型對環境反饋自我修正的 loop（/goal 或 Outcomes），以及自我管理 context（memory）的機制</li></ol><h3 id="關鍵數據" tabindex="-1">關鍵數據 <a class="header-anchor" href="#關鍵數據" aria-label="Permalink to &quot;關鍵數據&quot;">​</a></h3><ul><li>Parameter Golf：Fable 5 training pipeline 改進 ~6× 於 Opus 4.7</li><li>Continual Learning Bench：Fable 5 verification coverage 73%（最強跑）vs Opus 4.7 17%（中位數）vs Sonnet 4.6 ~0%</li><li>CMA: 最多 8 小時長跑 + Outcomes grader 確認全部 9 項 criteria 達標</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li>作者為 Anthropic 官方工程師，可信度高，但非完全獨立測試</li><li>Parameter Golf 是 toy benchmark；實際 codebase 上的表現需更多數據</li><li>&quot;verifier sub-agent 優於 self-critique&quot; 有重要 caveat：兩個 agent 同模型共享 blind spots，不是真正獨立第二意見</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>理由</th></tr></thead><tbody><tr><td>A. Workspace 可行動性</td><td>9/10</td><td><code>/goal</code>/<code>Outcomes</code> 為直接可用 primitive；verifier sub-agent 立即可實作；記憶 progression 可導入 cc-workspace</td></tr><tr><td>B. 創新性</td><td>7/10</td><td>verifier sub-agent &gt; self-critique 有具體機制說明；記憶五段 progression 模型新穎</td></tr><tr><td>C. 證據品質</td><td>9/10</td><td>6× improvement + 73% vs 17% coverage 有量化；Outcomes grader 完成 9 項 criteria 有可重現實驗</td></tr><tr><td>D. 技術深度</td><td>8/10</td><td>CMA + 自託管 sandbox + /goal + Outcomes 全有操作細節；Parameter Golf 架構分析深入</td></tr><tr><td>E. 泛化性</td><td>8/10</td><td>verifier sub-agent 模式 + 記憶 progression + loop self-correction 全可泛化到任何 agent 系統</td></tr><tr><td><strong>加權總分</strong></td><td><strong>8.30/10</strong></td><td>A×0.3 + B×0.2 + C×0.2 + D×0.15 + E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule<br><strong>整合位置</strong>：<code>subagent-strategy.md</code>：verifier sub-agent &gt; self-critique（獨立 context window grading）；<code>core.md</code>：記憶五段 progression（fail→investigate→verify→distill→consult）；CLAUDE.md：<code>/goal</code> 作為 self-correction primitive<br><strong>整合狀態</strong>：待實作</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Mythos-class models like Claude Fable 5 have changed the way many of us work at Anthropic. I want to share two tips for getting the most out of this class of models.</p><p><strong>Self-correction loops</strong></p><p>There&#39;s been a lot of interest in loops recently. @bcherny has mentioned that &quot;(his) job is to write loops.&quot; Letting models hillclimb on an evaluation is a common recipe for improving task performance: /goal in Claude Code and Outcomes in Claude Managed Agent are primitives that let you apply this general recipe for your specific task.</p><p>As mentioned in our prompting guide, Fable 5 is good at self-correcting in a loop. A well designed goal or rubric adds feedback to the environment that Claude is running in. This let&#39;s Claude run, collect feedback via the goal or rubric, self-correct, and proceed until the goal or rubric is satisfied.</p><p>I&#39;ll share one toy example that I used to test Fable: Parameter Golf is an open source ML engineering challenge to train the best model that fits in a 16MB artifact in &lt; 10 minutes on 8xH100s.</p><p>It&#39;s a bit like @karpathy&#39;s autoresearch project: it tests the ability of an agent to edit basic training code (a single train_gpt.py file), launch training, poll the log, read the score, and decide what experiment to run next.</p><p>I compared Fable 5 to Opus 4.7 on this challenge using Claude Managed Agents (CMA). CMA provides the agent harness as well as a hosted sandbox, so it&#39;s well-suited for long-running tasks with Fable 5. For Parameter Golf, I gave CMA access to 8xH100 GPUs as a self-hosted sandbox.</p><p>One subtle point: what does the judging is important. We&#39;ve seen that models have problems with self-critique on their own outputs. Prithvi Rajasekaran wrote about this in our engineering blog.</p><p>We&#39;ve found that a verifier sub-agent tends to outperform self-critique with Fable 5, because grading is done in an independent context window. Outcomes in CMA handles this by spawning a grader sub-agent for you.</p><p>For each test, I supplied a rubric (a file) with the nine checkable criteria (e.g., run a baseline, run 20 experiments, etc). Then, I ran Parameter Golf for up to 8 hours. The Outcomes grader confirmed that all experimental criteria were met before allowing Claude to stop the work.</p><p>Fable 5 improved the training pipeline ~6x more than Opus 4.7. If we consider experiments as structural (e.g., architecture changes) or scalar (e.g., adjusts a constant), Fable 5 bet on larger structural changes and showed resilience (e.g., pushing through a quantization regression to its biggest win).</p><p>Opus 4.7&#39;s first experiment produced a small win and nearly everything after followed the same template: adjust a scalar, measure, keep if positive.</p><p><strong>Memory</strong></p><p>Memory is another area where Fable excels. We can think about this as a outer loop that spans across sessions: Claude writes to memory during a session and those memories can be retrieved in future sessions.</p><p>@pgasawa and team recently published Continual Learning Bench 1.0, so I wanted to test this on Fable 5 vs earlier models.</p><p>I compared Fable 5, Opus 4.7, and Sonnet 4.6 on one of the tasks from the benchmark: the task asks an agent to answer sequential questions given access to a SQL database. Each question is a separate agent session and memory is provided.</p><p>For this, I used CMA with memory, which gives each agent access to a mounted filesystem that can be shared across sessions.</p><p>For this task, effective use of memory benefits from a progression: fail (get something wrong and document), investigate (before moving on, figure out why), verify (turn the diagnosis into a checked fact), distill (turn verification into a general rule), and consult (read the rule, instead of re-deriving it).</p><p>Sonnet 4.6 exits around step 1: its store is a list of failure notes and open guesses (e.g., &quot;maybe prc instead of prc_usd?&quot;). It rarely consults prior notes. To improve performance, task-specific memory instructions are needed.</p><p>Opus 4.7 exits around step 3: it creates a schema reference with uncertainty flagged (e.g., &quot;possibly prc in cents? Verify.&quot;), but verification coverage is low: at 7-33% of questions (median run ~17%).</p><p>Fable 5 tends to complete the progression: in its strongest runs, verification coverage is up to 73% (22 of 30) and it distills learnings into general rules that help with future tasks.</p><p>Rather than directly prompting and steering Fable 5, it&#39;s often better to design loops that let the model to self-correct in response to environment feedback (e.g., /goal or Outcomes) and manage its own context (e.g., via memory).</p><p>I&#39;ve shared just a few small scale experiments that I&#39;ve run, but its worth testing Fable 5 for yourself on challenging tasks and using loops for self-correction or memory.</p>',40)])])}const h=t(i,[["render",n]]);export{u as __pageData,h as default};
